import { beforeAll, describe, it } from 'bun:test'
import { TestApp } from '@guren/testing'
import app from '../src/app.js'

describe('Auth pages', () => {
  let http: TestApp

  beforeAll(async () => {
    http = await TestApp.fromApp(app)
  })

  it('renders login page in English by default', async () => {
    const response = await http.get('/login')
    const html = await response.text()

    // Check for English text
    if (!html.includes('Sign in') && !html.includes('Email')) {
      throw new Error('English login page should contain "Sign in" or "Email"')
    }
  })

  it('renders login page in Japanese with ja Accept-Language header', async () => {
    const response = await http
      .get('/login')
      .header('Accept-Language', 'ja-JP,ja;q=0.9')

    const html = await response.text()

    // Check for Japanese text (ログイン = login, メールアドレス = email address)
    if (!html.includes('ログイン') && !html.includes('メールアドレス')) {
      throw new Error('Japanese login page should contain "ログイン" or "メールアドレス"')
    }
  })

  it('renders register page in English by default', async () => {
    const response = await http.get('/register')
    const html = await response.text()

    // Check for English text
    if (!html.includes('Create an account') && !html.includes('Name')) {
      throw new Error('English register page should contain "Create an account" or "Name"')
    }
  })

  it('renders register page in Japanese with ja Accept-Language header', async () => {
    const response = await http
      .get('/register')
      .header('Accept-Language', 'ja-JP,ja;q=0.9')

    const html = await response.text()

    // Check for Japanese text (アカウント登録 = create account, 名前 = name)
    if (!html.includes('アカウント登録') && !html.includes('名前')) {
      throw new Error('Japanese register page should contain "アカウント登録" or "名前"')
    }
  })
})
EOF
